const PROMPTS = join(import.meta.dirname, '..', 'prompts')
export const INSTRUCTIONS_PATH = join(PROMPTS, 'agent.md')
export const AGENTS_DIR = join(PROMPTS, 'agents')
const CLI_PATH = join(import.meta.dirname, 'cli.ts')
const DEFAULT_CLI = `"${process.execPath}" "${CLI_PATH}"`
/** How the prompts name the CLI. It is right only inside werk's own checkout. */
const LOCAL_CLI = 'node src/cli.ts'

function read(path: string): string | undefined {
  try {
    return readFileSync(path, 'utf8')
  } catch {
    return undefined
  }
}

/** A werk checkout with the same instructions: its own instruction file imports the text and
 *  its own agent directory holds the subagents, so Claude Code reads both there already, and
 *  the local CLI path is right. */
function isWerkCheckout(cwd: string, text: string): boolean {
  const local = join(cwd, 'prompts', 'agent.md')
  return existsSync(local) && read(local) === text
}

/** The system prompt to append for a `claude` child that runs in `cwd`: `extra` and the
 *  instructions, with every CLI command named by the path werk runs from. In a werk checkout,
 *  only `extra`, unchanged. A missing file gives `extra` alone, so a broken install starts
 *  agents with less guidance instead of not starting them. */
export function systemPrompt(cwd: string, extra = '', cli = DEFAULT_CLI): string {
  const text = read(INSTRUCTIONS_PATH)
  if (text === undefined || isWerkCheckout(cwd, text)) return extra
  return [extra, text].filter(Boolean).join('\n\n').replaceAll(LOCAL_CLI, cli)
}

export type AgentDef = { description: string; prompt: string; tools?: string[] }

/** One subagent file: a front matter of `name`, `description` and `tools`, then the prompt. */
export function parseAgent(file: string, cli = DEFAULT_CLI): [string, AgentDef] | undefined {
  const m = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(file)
  if (!m) return undefined
  const field = (k: string) => new RegExp(`^${k}:[ \\t]*(.*)$`, 'm').exec(m[1])?.[1].trim()
  const name = field('name')
  const description = field('description')
  if (!name || !description) return undefined
  const tools = field('tools')
  const def: AgentDef = { description: description.replaceAll(LOCAL_CLI, cli), prompt: m[2].trim().replaceAll(LOCAL_CLI, cli) }
  if (tools) def.tools = tools.split(',').map((t) => t.trim()).filter(Boolean)
  return [name, def]
}

/** The subagents that ship with the instructions, by name. Empty in a werk checkout. */
export function shippedAgents(cwd: string, cli = DEFAULT_CLI): Record<string, AgentDef> {
  const text = read(INSTRUCTIONS_PATH)
  if (text === undefined || isWerkCheckout(cwd, text)) return {}
  let files: string[]
  try {
    files = readdirSync(AGENTS_DIR).filter((f) => f.endsWith('.md'))
  } catch {
    return {}
  }
  const out: Record<string, AgentDef> = {}
  for (const f of files.sort()) {
    const parsed = parseAgent(read(join(AGENTS_DIR, f)) ?? '', cli)
    if (parsed) out[parsed[0]] = parsed[1]
  }
  return out
}

/** The CLI arguments that hand `systemPrompt` and `shippedAgents` to a `claude` child. Each
 *  flag is left out when it would be empty. */
export function instructionArgs(cwd: string, extra = ''): string[] {
  const text = systemPrompt(cwd, extra)
  const agents = shippedAgents(cwd)
  return [
    ...(text ? ['--append-system-prompt', text] : []),
    ...(Object.keys(agents).length ? ['--agents', JSON.stringify(agents)] : []),
  ]
}

